const webhookData = $('Webhook Tin Nhan Khach Hang').first().json;
const body = webhookData.body || webhookData || {};
const customerName = String(body.customerName || 'Khach hang').trim();
const customerId = String(body.customerId || body.phone || 'unknown').trim();
const question = String(body.message || '').trim();
const faqRaw = $input.first().json;
const faqList = Array.isArray(faqRaw) ? faqRaw : (Array.isArray(faqRaw.items) ? faqRaw.items : []);

const tokens = question.toLowerCase().split(/\s+/).filter((t) => t.length >= 2);
const scored = faqList.map((entry) => {
  const hay = `${entry.q || entry.question || ''} ${entry.a || entry.answer || ''}`.toLowerCase();
  let score = 0;
  for (const tk of tokens) {
    if (hay.includes(tk)) score += 1;
  }
  return { entry, score };
}).sort((a, b) => b.score - a.score).slice(0, 4);

const context = scored.map((s, idx) => `FAQ #${idx + 1}: H: ${s.entry.q || s.entry.question || ''} | D: ${s.entry.a || s.entry.answer || ''}`).join('\n');
const hasComplaint = /(khieu nai|lua dao|hoan tien|bao hanh loi|gap nhan vien|goi dien)/i.test(question);

return [{
  json: {
    customerName,
    customerId,
    question,
    hasComplaint,
    context: context || 'Khong tim thay muc FAQ khop truc tiep.'
  }
}];

