const src = $('Loc Top FAQ & Phat hien Khieu nai').first().json;
const raw = $input.first().json.choices?.[0]?.message?.content || '{}';
let parsed = { reply: '', confidence: 0, needHuman: true };
try {
  parsed = JSON.parse(raw);
} catch (_err) {
  parsed = { reply: '', confidence: 0, needHuman: true };
}
const confidence = Number(parsed.confidence || 0);
const autoReplyOk = !src.hasComplaint && !parsed.needHuman && confidence >= 0.75 && String(parsed.reply || '').trim().length > 0;

return [{
  json: {
    customerName: src.customerName,
    customerId: src.customerId,
    question: src.question,
    confidence,
    autoReplyOk,
    reply: autoReplyOk
      ? String(parsed.reply).trim()
      : 'Cam on ban da lien he! Yeu cau cua ban da duoc chuyen ngay cho nhan vien CSKH de ho tro chinh xac nhat trong it phut.',
    escalationText: [
      'CAN NHAN VIEN CSKH HO TRO GAP',
      `Khach: ${src.customerName} (${src.customerId})`,
      `Cau hoi: ${src.question}`,
      `Do tin cay AI: ${confidence} | Khieu nai: ${src.hasComplaint ? 'CO' : 'KHONG'}`
    ].join('\n')
  }
}];
